import React, { useState } from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import ThoughtSpotShell from './components/ThoughtSpotShell';
import { TierProvider } from './config/TierContext';
import Sidebar, { SIDEBAR_WIDTH } from './components/NavHeader';
import TopHeader from './components/TopHeader';
import SignInPage from './pages/SignInPage';
import HomePage from './pages/HomePage';
import DashboardHome from './pages/DashboardHome';
import SearchPage from './pages/SearchPage';
import PlaceholderPage from './pages/PlaceholderPage';
import Analytics from './pages/Analytics';
import LiveboardTabPage from './pages/LiveboardTabPage';
import './App.css';

function App() {
  const [signedIn, setSignedIn] = useState<boolean>(
    () => !!localStorage.getItem('vl_auth')
  );

  const handleSignIn = () => {
    localStorage.setItem('vl_auth', '1');
    setSignedIn(true);
  };

  if (!signedIn) {
    return <SignInPage onSignIn={handleSignIn} />;
  }

  return (
    <TierProvider>
      <ThoughtSpotShell>
        <Router>
            <div className="App" style={{ display: 'flex', minHeight: '100vh', backgroundColor: '#FFFFFF' }}>
            <Sidebar />
            <div
              style={{
                marginLeft: SIDEBAR_WIDTH,
                flex: 1,
                minHeight: '100vh',
                display: 'flex',
                flexDirection: 'column',
              }}
            >
              <TopHeader />
              <main style={{ flex: '1 1 auto', width: '100%', minWidth: 0, display: 'flex', flexDirection: 'column' }}>
                <Routes>
                  <Route path="/" element={<Navigate to="/home" replace />} />
                  <Route path="/home" element={<HomePage />} />
                  <Route path="/dashboard" element={<DashboardHome />} />
                  <Route
                    path="/sales"
                    element={
                      <LiveboardTabPage
                        title="Sales Performance"
                        description="Revenue, units sold, top categories and channel performance across all retail locations."
                        tabId="04f23f50-9b02-460f-b3cd-e635bd10d85c"
                      />
                    }
                  />
                  <Route
                    path="/finance"
                    element={
                      <LiveboardTabPage
                        title="Finance Overview"
                        description="Margin analysis, cost of goods, gross profit, and financial KPIs by period and category."
                        tabId="2ac01db3-436a-4570-bf09-5d9d478bc81c"
                      />
                    }
                  />
                  <Route path="/analytics" element={<Analytics />} />
                  <Route path="/search" element={<SearchPage />} />
                  <Route
                    path="/pricing"
                    element={<PlaceholderPage title="Pricing & Promotions" description="Markdown analysis, promotional lift, pricing elasticity and discount performance by collection." />}
                  />
                  <Route path="/knowledge-hub" element={<PlaceholderPage title="Knowledge Hub" />} />
                </Routes>
              </main>
            </div>
          </div>
        </Router>
      </ThoughtSpotShell>
    </TierProvider>
  );
}

export default App;
